32	export function formatBRL(n: number): string {
33	    if (n === 0) return 'R$ 0,00';
34	    return n.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });
35	}
36	
37	export function parseBRL(v: string | number | undefined): number {
38	    if (!v && v !== 0) return 0;
39	    let s = String(v)
40	        .replace(/[^\d,.-]/g, '')
41	        .trim();
42	    if (!s) return 0;
43	    const commaMatch = s.match(/,(\d{1,2})$/);
44	    if (commaMatch) {
45	        s = s.replace(/\./g, '').replace(',', '.');
46	    } else {
47	        const dotMatch = s.match(/\.(\d{1,2})$/);
48	        if (dotMatch && !s.includes(',')) {
49	            // US decimal, leave as-is
50	        } else {
51	            s = s.replace(/\./g, '');
52	        }
53	    }
54	    return parseFloat(s) || 0;
55	}
