207	        .map((i) => {
208	            const p = i._posAquisicao || ({} as any);
209	            const refDate = p.ultimaMovimentacao || p.dataAquisicao;
210	            const dias = refDate
211	                ? Math.round((Date.now() - new Date(refDate).getTime()) / (1000 * 60 * 60 * 24))
212	                : 0;
213	            const et = allDashEtapas.find((e) => e.id === p.etapaAtual) || allDashEtapas[0];
214	            return {
215	                itemId: i.id,
